<script setup>
import { ref, computed, onUnmounted } from 'vue'
import { LayoutDashboard, Files, SlidersHorizontal, Bookmark, Sparkles, UploadCloud, ArrowUpRight, Search, ChevronRight, Car, X, Check, LogOut, RefreshCw, FileText, AlertTriangle } from 'lucide-vue-next'
const username=ref('admin'), password=ref(''), auth=ref(''), view=ref('dashboard'), error=ref(''), busy=ref(false)
const catalogs=ref([]), selected=ref(null), lots=ref([]), analysis=ref(null), history=ref([]), config=ref({}), file=ref(null), house=ref('JBA'), query=ref(''), filter=ref('ALL')
const detail=ref(null), edit=ref(null), uploadInput=ref(null), inputRate=ref(0), outputRate=ref(0)
const criteria=ref({capital:65000000,maxPerUnit:65000000,targetProfit:5000000,auctionFee:2500000,auctionFeePercent:0,repairBuffer:3000000,taxBuffer:2000000,otherCosts:1000000,riskBuffer:2000000,minYear:2012,maxKilometer:150000,transmission:'ALL',buyer:'DEALER',strategy:'FAST',requireStnk:true,requireBpkb:true,instructions:''})
const moneyFields=[['capital','Modal tersedia'],['maxPerUnit','Modal maksimal / unit'],['targetProfit','Target laba bersih'],['auctionFee','Biaya lelang tetap'],['repairBuffer','Buffer servis'],['taxBuffer','Buffer pajak'],['otherCosts','Transport & biaya lain'],['riskBuffer','Cadangan risiko']]
const nav=[['dashboard','Overview',LayoutDashboard],['catalogs','Katalog lelang',Files],['analysis','Analisis unit',SlidersHorizontal],['watchlist','Bid board',Bookmark],['ai','AI & penggunaan',Sparkles]]
let timer, polling=false
const idr=v=>v==null?'—':new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(v)
const short=v=>v==null?'—':`${new Intl.NumberFormat('id-ID',{maximumFractionDigits:1}).format(v/1000000)} jt`
const results=computed(()=>analysis.value?.results||[])
const visible=computed(()=>results.value.filter(r=>(view.value!=='watchlist'||r.watchlisted)&&(filter.value==='ALL'||r.recommendation===filter.value)&&`${r.vehicle} ${r.lotNumber}`.toLowerCase().includes(query.value.toLowerCase())))
const bids=computed(()=>results.value.filter(r=>r.recommendation==='BID').length)
const top=computed(()=>results.value.find(r=>r.recommendation==='BID'))
const usageCost=computed(()=>((analysis.value?.usage?.inputTokens||0)*inputRate.value+(analysis.value?.usage?.outputTokens||0)*outputRate.value)/1000000)
async function api(path,options={}){
 const headers={'Authorization':`Basic ${auth.value}`,'X-PhiveGarage':'web',...options.headers}
 if(options.body && !(options.body instanceof FormData))headers['Content-Type']='application/json'
 const response=await fetch(`/api${path}`,{...options,headers})
 if(response.status===401){auth.value='';throw Error('Username atau password tidak cocok.')}
 if(!response.ok){let data;try{data=await response.json()}catch{}throw Error(data?.message||data?.detail||`Request gagal (${response.status})`)}
 return response.json()
}
async function perform(action){error.value='';busy.value=true;try{await action()}catch(e){error.value=e.message}finally{busy.value=false}}
async function login(){await perform(async()=>{auth.value=btoa(unescape(encodeURIComponent(`${username.value}:${password.value}`)));try{config.value=await api('/config');await refreshCatalogs();password.value='';timer=setInterval(poll,2500)}catch(e){auth.value='';throw e}})}
function logout(){auth.value='';clearInterval(timer);catalogs.value=[];selected.value=null;lots.value=[];analysis.value=null;history.value=[]}
async function refreshCatalogs(){catalogs.value=await api('/catalogs')}
async function loadCatalog(c){await perform(async()=>{selected.value=await api(`/catalogs/${c.id}`);lots.value=await api(`/catalogs/${c.id}/lots`);history.value=await api(`/catalogs/${c.id}/analyses`);analysis.value=history.value[0]||null;if(analysis.value?.parameters)criteria.value={...analysis.value.parameters};view.value='analysis'})}
async function poll(){
 if(!auth.value||polling)return;polling=true
 try{
  if(catalogs.value.some(c=>['QUEUED','EXTRACTING'].includes(c.status)))await refreshCatalogs()
  if(selected.value&&['QUEUED','EXTRACTING'].includes(selected.value.status)){
   selected.value=await api(`/catalogs/${selected.value.id}`)
   if(selected.value.status==='READY')lots.value=await api(`/catalogs/${selected.value.id}/lots`)
  }
  if(analysis.value&&['QUEUED','PROCESSING'].includes(analysis.value.status)){
   analysis.value=await api(`/analyses/${analysis.value.id}`)
   if(['READY','FAILED'].includes(analysis.value.status))history.value=await api(`/catalogs/${selected.value.id}/analyses`)
  }
 }catch(e){error.value=e.message}finally{polling=false}
}
onUnmounted(()=>clearInterval(timer))
async function upload(){await perform(async()=>{
 if(!file.value)throw Error('Pilih PDF katalog terlebih dahulu.')
 const body=new FormData();body.append('file',file.value);body.append('house',house.value)
 const c=await api('/catalogs',{method:'POST',body});await refreshCatalogs();await loadCatalog(c);file.value=null;if(uploadInput.value)uploadInput.value.value=''
})}
async function retryExtraction(){await perform(async()=>{await api(`/catalogs/${selected.value.id}/retry`,{method:'POST'});selected.value=await api(`/catalogs/${selected.value.id}`);await refreshCatalogs()})}
async function run(){await perform(async()=>{const a=await api(`/catalogs/${selected.value.id}/analyses`,{method:'POST',body:JSON.stringify(criteria.value)});analysis.value=await api(`/analyses/${a.id}`);history.value=await api(`/catalogs/${selected.value.id}/analyses`)})}
async function setWatch(r){await perform(async()=>{await api(`/analyses/${analysis.value.id}/watchlist/${r.lotId}`,{method:'PATCH',body:JSON.stringify({watchlisted:!r.watchlisted})});r.watchlisted=!r.watchlisted})}
function openEdit(lot){edit.value=JSON.parse(JSON.stringify(lot));edit.value.data.comparables||=[]}
async function saveLot(){await perform(async()=>{for(const k of ['year','kilometer','basePrice','repairCost','taxCost','otherCost','taxExpiry'])if(edit.value.data[k]==='')edit.value.data[k]=null;await api(`/lots/${edit.value.id}`,{method:'PUT',body:JSON.stringify({data:edit.value.data,verified:edit.value.verified})});lots.value=await api(`/catalogs/${selected.value.id}/lots`);edit.value=null})}
async function openPdf(){await perform(async()=>{const res=await fetch(`/api/catalogs/${selected.value.id}/pdf`,{headers:{Authorization:`Basic ${auth.value}`,'X-PhiveGarage':'web'}});if(!res.ok)throw Error('PDF gagal dibuka');const url=URL.createObjectURL(await res.blob());window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)})}
function download(){const body=JSON.stringify({catalog:selected.value,analysis:analysis.value},null,2);const url=URL.createObjectURL(new Blob([body],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='phivegarage-analysis.json';a.click();URL.revokeObjectURL(url)}
const statusLabel=s=>({BID:'Layak bid',REVIEW:'Perlu diperiksa',SKIP:'Lewati',QUEUED:'Dalam antrean',EXTRACTING:'Membaca PDF',PROCESSING:'Menganalisis',READY:'Siap',FAILED:'Gagal'})[s]||s
</script>

<template>
 <div v-if="!auth" class="login-shell"><div class="login-art"><div class="brand"><span class="brand-mark">P</span> phivegarage<span class="brand-dot">.</span></div><div><span class="eyebrow">AUCTION INTELLIGENCE</span><h1>Bid dengan data.<br>Putar modal<br><em>lebih terarah.</em></h1><p>Dari katalog lelang ke shortlist pilihanmu.<br>Satu tempat untuk menilai risiko dan menghitung batas bid.</p></div><small>BUILT FOR YOUR NEXT GOOD DEAL</small></div><form class="login-card" @submit.prevent="login"><span class="eyebrow">WELCOME TO YOUR GARAGE</span><h2>Masuk ke workspace</h2><p>Gunakan akun yang kamu konfigurasi di server.</p><label>Username<input v-model="username" autocomplete="username" required></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required></label><div v-if="error" class="error">{{ error }}</div><button class="primary" :disabled="busy">{{ busy?'Menghubungkan…':'Masuk' }} <ArrowUpRight :size="18"/></button></form></div>
 <div v-else class="app-shell">
 <aside class="sidebar"><div class="brand"><span class="brand-mark">P</span> phivegarage<span class="brand-dot">.</span></div><span class="workspace-label">PERSONAL WORKSPACE</span><nav><button v-for="[id,label,icon] in nav" :key="id" :class="{active:view===id}" @click="view=id"><component :is="icon" :size="19"/>{{label}}<ChevronRight v-if="view===id" :size="15"/></button></nav><div class="sidebar-note"><span class="live-dot"></span> Decision support<p>Periksa unit langsung sebelum bidding. Hasil analisis membantu menilai, bukan menjamin kondisi.</p></div><button class="account" @click="logout"><span class="avatar">{{ username.slice(0,1).toUpperCase() }}</span><span>{{username}}<small>Private garage</small></span><LogOut :size="17"/></button></aside>
 <main><header class="topbar"><span>Workspace <ChevronRight :size="14"/> <b>{{nav.find(n=>n[0]===view)?.[1]}}</b></span><span class="topbar-status"><span class="live-dot"></span> {{config.aiConfigured?'AI terhubung':'AI belum dikonfigurasi'}}</span></header>
 <div class="content"><div v-if="error" class="error banner" role="alert">{{error}}<button class="icon-button" @click="error=''">×</button></div>
 <template v-if="view==='dashboard'">
 <div class="page-heading"><div><span class="eyebrow">YOUR AUCTION WORKSPACE</span><h1>Temukan ruang untung.</h1><p>Mulai dari katalog. Akhiri dengan batas bid yang jelas.</p></div><button class="primary" @click="view='catalogs'"><UploadCloud :size="18"/> Upload katalog</button></div>
 <div class="stats"><article><span>Katalog tersimpan</span><strong>{{catalogs.length.toString().padStart(2,'0')}}</strong><small>Seluruh sesi lelang</small></article><article><span>Unit dianalisis</span><strong>{{results.length.toString().padStart(2,'0')}}</strong><small>{{selected?.name||'Belum ada analisis aktif'}}</small></article><article><span>Layak bid</span><strong class="green">{{bids.toString().padStart(2,'0')}}</strong><small>Memenuhi filter & perhitungan</small></article><article><span>Profit kandidat teratas</span><strong>{{short(top?.profit)}}</strong><small>Estimasi pada harga dasar</small></article></div>
 <div class="overview-grid"><section class="hero-panel"><span class="eyebrow">A CLEARER WAY TO BID</span><h2>Harga murah belum<br>tentu <em>deal yang bagus.</em></h2><p>Hitung biaya, tandai risiko, dan pilih unit yang masuk dengan strategi kamu.</p><button @click="view='catalogs'">Mulai analisis <ArrowUpRight :size="20"/></button><div class="hero-numbers"><div><small>01</small><b>Upload PDF</b></div><div><small>02</small><b>Atur strategi</b></div><div><small>03</small><b>Tentukan max bid</b></div></div></section><section class="panel formula"><span class="eyebrow">THE BID DISCIPLINE</span><h3>Batas bid, bukan feeling.</h3><p>Harga jual konservatif</p><p>− Target profit</p><p>− Servis, pajak & cadangan</p><p>− Biaya lelang</p><div class="formula-result">= Max bid aman <Check :size="20"/></div><small>Batas ini juga dibatasi modal tersedia dan biaya lelang persentase.</small></section></div>
 <section class="panel"><div class="section-head"><h3>Katalog terbaru</h3><button class="text-button" @click="view='catalogs'">Lihat semua <ArrowUpRight :size="16"/></button></div><div v-if="!catalogs.length" class="empty"><Files :size="32"/><h3>Garasi analisis masih kosong</h3><p>Upload katalog PDF untuk mulai menyeleksi unit lelang.</p></div><button v-for="c in catalogs.slice(0,4)" :key="c.id" class="catalog-row" @click="loadCatalog(c)"><span class="file-icon"><FileText :size="22"/></span><span><b>{{c.name}}</b><small>{{c.house}} · {{c.total_lots}} unit</small></span><span class="badge" :class="c.status">{{statusLabel(c.status)}}</span><ChevronRight :size="18"/></button></section>
 </template>
 <template v-if="view==='catalogs'">
 <div class="page-heading"><div><span class="eyebrow">START WITH THE SOURCE</span><h1>Katalog lelang</h1><p>PDF tersimpan. Hasil ekstraksi bisa dikoreksi dan dianalisis ulang.</p></div><button class="secondary" @click="perform(refreshCatalogs)"><RefreshCw :size="16"/> Refresh</button></div>
 <section class="panel upload-panel"><div class="upload-symbol"><UploadCloud :size="35"/></div><div><h3>Bawa katalog berikutnya ke garasi.</h3><p>PDF teks atau scan · maksimal 20 MB / 150 halaman</p><p class="muted">Ekstraksi memanggil OpenAI API dan memakai kuota API server kamu.</p></div><form @submit.prevent="upload"><select v-model="house"><option v-for="h in ['JBA','IBID','Auksi','Otomas','Smartbid','Tribik','Lainnya']" :key="h">{{h}}</option></select><input ref="uploadInput" type="file" accept="application/pdf,.pdf" @change="file=$event.target.files[0]" required><button class="primary" :disabled="busy||!config.aiConfigured">{{busy?'Mengunggah…':'Upload & ekstrak'}}<ArrowUpRight :size="17"/></button></form></section>
 <section class="panel"><div class="section-head"><h3>Semua katalog <span class="count">{{catalogs.length}}</span></h3></div><div v-if="!catalogs.length" class="empty"><Files :size="30"/><p>Belum ada katalog. Pilih file PDF di atas.</p></div><button v-for="c in catalogs" :key="c.id" class="catalog-row" @click="loadCatalog(c)"><span class="file-icon"><FileText :size="22"/></span><span><b>{{c.name}}</b><small>{{c.house}} · {{c.total_lots}} unit · {{new Date(c.created_at).toLocaleDateString('id-ID')}}<em v-if="c.error">{{c.error}}</em></small></span><span class="badge" :class="c.status">{{statusLabel(c.status)}} <template v-if="c.status==='EXTRACTING'">{{c.progress}}%</template></span><ChevronRight :size="18"/></button></section>
 </template>
 <template v-if="['analysis','watchlist'].includes(view)">
 <div class="page-heading"><div><span class="eyebrow">{{view==='watchlist'?'YOUR BIDDING SHORTLIST':'FROM CATALOG TO DECISION'}}</span><h1>{{view==='watchlist'?'Bid board':'Analisis unit'}}</h1><p>{{selected?`${selected.house} · ${selected.name}`:'Pilih katalog untuk membuka workspace analisis.'}}</p></div><div class="heading-actions"><button v-if="selected" class="secondary" @click="openPdf"><FileText :size="16"/> PDF sumber</button><button v-if="analysis?.status==='READY'" class="secondary" @click="download">Export JSON</button></div></div>
 <div v-if="!selected" class="panel empty"><Car :size="38"/><h3>Belum ada katalog dipilih</h3><p>Buka katalog lelang untuk melihat unit dan analisisnya.</p><button class="primary" @click="view='catalogs'">Pilih katalog</button></div>
 <template v-else>
 <div v-if="selected.status!=='READY'" class="panel process-state"><RefreshCw :size="25"/><h3>{{statusLabel(selected.status)}}</h3><p>{{selected.error||`Ekstraksi katalog ${selected.progress}%. Status diperbarui otomatis.`}}</p><button v-if="selected.status==='FAILED'" class="primary" :disabled="busy" @click="retryExtraction"><RefreshCw :size="16"/> Coba ulang ekstraksi</button></div>
 <template v-else>
 <section v-if="view==='analysis'" class="panel strategy-panel"><div class="section-head"><div><span class="eyebrow">YOUR RULES, YOUR CAPITAL</span><h3>Parameter analisis</h3></div><span class="tag">IDR</span></div><form @submit.prevent="run"><div class="field-grid"><label v-for="[key,label] in moneyFields" :key="key">{{label}}<input v-model.number="criteria[key]" type="number" :min="['capital','maxPerUnit'].includes(key)?1:0" max="100000000000" step="100000" required></label><label>Biaya lelang (%)<input v-model.number="criteria.auctionFeePercent" type="number" min="0" max="100" step="0.01" required></label><label>Tahun minimal<input v-model.number="criteria.minYear" type="number" min="1950" max="2100" required></label><label>KM maksimal<input v-model.number="criteria.maxKilometer" type="number" min="1" required></label><label>Transmisi<select v-model="criteria.transmission"><option value="ALL">Semua</option><option value="MT">Manual</option><option value="AT">Automatic / CVT</option></select></label><label>Target pembeli<select v-model="criteria.buyer"><option value="DEALER">Pedagang</option><option value="RETAIL">Retail</option></select></label><label>Strategi<select v-model="criteria.strategy"><option value="FAST">Perputaran cepat</option><option value="BALANCED">Seimbang</option><option value="MARGIN">Prioritas margin</option></select></label></div><div class="checks"><label><input v-model="criteria.requireStnk" type="checkbox"> Wajib STNK ada</label><label><input v-model="criteria.requireBpkb" type="checkbox"> Wajib BPKB ada</label></div><label>Instruksi tambahan<textarea v-model="criteria.instructions" maxlength="3000" rows="2" placeholder="Contoh: Fokus mobil yang mudah dijual ke pedagang Jakarta/Bekasi. Tandai risiko transmisi dan surat-surat."/></label><div class="form-footer"><p><Sparkles :size="16"/> Data tersimpan dipakai kembali. Analisis ulang menggunakan kuota API.</p><button class="primary" :disabled="busy||['QUEUED','PROCESSING'].includes(analysis?.status)"><Sparkles :size="17"/>{{analysis?'Analisis ulang':'Analisis katalog'}}</button></div></form></section>
 <section v-if="view==='analysis'" class="panel"><div class="section-head"><div><h3>Periksa hasil ekstraksi <span class="count">{{lots.length}}</span></h3><p>Verifikasi lot dan isi pembanding harga agar unit dapat berstatus BID.</p></div></div><div class="table-wrap"><table><thead><tr><th>LOT</th><th>UNIT</th><th>HARGA DASAR</th><th>SUMBER</th><th>VERIFIKASI</th><th/></tr></thead><tbody><tr v-for="l in lots" :key="l.id"><td class="lot-no">{{l.lot_number}}</td><td><b>{{l.data.vehicle}}</b><small>{{l.data.year||'Tahun ?'}} · {{l.data.transmission||'Transmisi ?'}} · {{l.data.kilometer?.toLocaleString('id-ID')||'?'}} km</small></td><td>{{idr(l.data.basePrice)}}</td><td>Hal. {{l.data.sourcePage||'?'}}</td><td><span class="badge" :class="l.verified?'BID':'REVIEW'">{{l.verified?'Terverifikasi':'Periksa'}}</span></td><td><button class="text-button" @click="openEdit(l)">Edit <ChevronRight :size="14"/></button></td></tr></tbody></table></div></section>
 <section v-if="analysis" class="panel"><div class="section-head"><div><span class="eyebrow">THE DEAL SHORTLIST</span><h3>{{view==='watchlist'?'Unit pilihan kamu':'Ranking & rekomendasi'}}</h3><p>Perhitungan profit memakai harga dasar. Hasil adalah snapshot pada waktu analisis.</p></div><select v-if="history.length" :value="analysis.id" @change="perform(async()=>{analysis=await api('/analyses/'+$event.target.value);criteria={...analysis.parameters}})"><option v-for="h in history" :key="h.id" :value="h.id">{{new Date(h.created_at).toLocaleString('id-ID')}} · {{statusLabel(h.status)}}</option></select></div><div v-if="analysis.status!=='READY'" class="process-state"><RefreshCw :size="25"/><h3>{{statusLabel(analysis.status)}}</h3><p>{{analysis.error||'AI sedang menilai unit. Hasil akan muncul otomatis.'}}</p></div><template v-else><div class="table-tools"><label class="search"><Search :size="16"/><input v-model="query" placeholder="Cari model atau nomor lot…"></label><div class="filter-tabs"><button v-for="[id,label] in [['ALL','Semua'],['BID','Layak bid'],['REVIEW','Periksa'],['SKIP','Lewati']]" :key="id" :class="{active:filter===id}" @click="filter=id">{{label}}</button></div></div><div class="table-wrap"><table><thead><tr><th>LOT / UNIT</th><th>STATUS</th><th>SKOR</th><th>HARGA DASAR</th><th>MAX BID</th><th>JUAL KONSERVATIF</th><th>LABA</th><th/></tr></thead><tbody><tr v-for="r in visible" :key="r.lotId" @click="detail=r" class="clickable"><td><small>LOT {{r.lotNumber}}</small><b>{{r.vehicle}}</b></td><td><span class="badge" :class="r.recommendation">{{statusLabel(r.recommendation)}}</span></td><td><span class="score" :class="{green:r.score>=75}">{{r.score}}<small>/100</small></span></td><td>{{short(r.basePrice)}}</td><td class="strong">{{short(r.maxBid)}}</td><td>{{short(r.sellPrice)}}</td><td :class="r.profit>0?'green':'red'">{{short(r.profit)}}</td><td><button class="icon-button" :class="{saved:r.watchlisted}" :aria-label="r.watchlisted?'Hapus dari bid board':'Simpan ke bid board'" @click.stop="setWatch(r)"><Bookmark :size="18"/></button></td></tr></tbody></table><div v-if="!visible.length" class="empty"><Bookmark :size="28"/><p>{{view==='watchlist'?'Simpan unit dari ranking untuk membangun bid board.':'Tidak ada unit sesuai filter.'}}</p></div></div><div class="table-foot"><AlertTriangle :size="15"/> Max bid belum tersedia tanpa pembanding. Estimasi AI tidak dipakai sebagai harga pasar terverifikasi.</div></template></section>
 </template></template>
 </template>
 <template v-if="view==='ai'"><div class="page-heading"><div><span class="eyebrow">TRANSPARENT INTELLIGENCE</span><h1>AI & penggunaan</h1><p>Lihat konfigurasi, penggunaan token, dan batas analisis.</p></div></div><div class="stats"><article><span>Model aktif</span><strong class="model-name">{{config.model}}</strong><small>{{config.aiConfigured?'API key dikonfigurasi':'API key belum tersedia'}}</small></article><article><span>Input token</span><strong>{{(analysis?.usage?.inputTokens||0).toLocaleString('id-ID')}}</strong><small>Analisis terpilih</small></article><article><span>Output token</span><strong>{{(analysis?.usage?.outputTokens||0).toLocaleString('id-ID')}}</strong><small>Analisis terpilih</small></article><article><span>Estimasi biaya analisis</span><strong>${{usageCost.toFixed(4)}}</strong><small>Berdasarkan tarif yang kamu isi</small></article></div><section class="panel"><h3>Tarif model (USD / 1 juta token)</h3><p>Isi tarif dari dashboard provider. Estimasi ini tidak termasuk ekstraksi PDF, cached token, maupun panggilan gagal.</p><div class="field-grid rates"><label>Input<input v-model.number="inputRate" type="number" min="0" step="0.01"></label><label>Output<input v-model.number="outputRate" type="number" min="0" step="0.01"></label></div></section><section class="panel ai-explanation"><h3>Bagaimana rekomendasi dibuat</h3><div><b>01 · Ekstrak fakta</b><p>PDF dibagi per 3 halaman. AI membaca spesifikasi dan mencatat sumber; field yang tidak terbaca dibiarkan kosong.</p></div><div><b>02 · Nilai risiko</b><p>AI memberikan indikasi kondisi, demand, estimasi servis, dan alasan sesuai parameter. Demand dan waktu jual belum memakai histori transaksi lokal.</p></div><div><b>03 · Hitung di Java</b><p>Harga jual memakai pembanding terendah × 95% untuk retail / 85% untuk pedagang. Ini asumsi konservatif yang harus kamu tinjau. Biaya, target profit, dan batas modal menghasilkan max bid.</p></div><div><b>04 · Verifikasi sebelum bid</b><p>Status BID memerlukan data terverifikasi, pembanding harga, dan filter yang terpenuhi. Tidak ada scraping harga otomatis pada MVP ini.</p></div></section></template>
 <footer>PHIVEGARAGE <span>Know the cost. Respect the limit.</span><small>MVP · 0.1</small></footer>
 </div></main>
 <div v-if="detail" class="modal-backdrop" @click.self="detail=null"><section class="modal"><button class="modal-close icon-button" @click="detail=null"><X/></button><span class="eyebrow">LOT {{detail.lotNumber}} · UNIT ANALYSIS</span><h2>{{detail.vehicle}}</h2><span class="badge" :class="detail.recommendation">{{statusLabel(detail.recommendation)}} · {{detail.score}}/100</span><div class="detail-stats"><div><small>MAX BID</small><strong>{{idr(detail.maxBid)}}</strong></div><div><small>TOTAL MODAL (HARGA DASAR)</small><strong>{{idr(detail.totalCost)}}</strong></div><div><small>HARGA JUAL KONSERVATIF</small><strong>{{idr(detail.sellPrice)}}</strong></div><div><small>ESTIMASI PROFIT</small><strong>{{idr(detail.profit)}}</strong></div></div><section v-if="detail.costs" class="cost-panel"><h3>Rincian biaya unit</h3><dl><template v-for="[key,label] in [['repair','Servis (buffer / input / AI tertinggi)'],['tax','Pajak & balik nama'],['globalOther','Transport & biaya global'],['lotOther','Biaya tambahan lot'],['riskBuffer','Cadangan risiko'],['auctionFeeAtBase','Biaya lelang pada harga dasar']]" :key="key"><dt>{{label}}</dt><dd>{{idr(detail.costs[key])}}</dd></template><dt>Total pada max bid</dt><dd>{{idr(detail.costs.totalAtMaxBid)}}</dd><dt>Profit pada max bid</dt><dd>{{idr(detail.costs.profitAtMaxBid)}}</dd></dl><p>Biaya lelang: {{idr(detail.costs.auctionFixedFee)}} tetap + {{detail.costs.auctionFeePercent}}% bid. Nilai di atas memakai parameter saat analisis dibuat.</p><p v-if="detail.maxBid===0">Tidak ada bid positif yang memenuhi modal dan target profit.</p></section><div v-if="detail.blockers.length" class="review-box"><h3>Yang perlu diselesaikan</h3><ul><li v-for="b in detail.blockers" :key="b">{{b}}</li></ul></div><h3>Alasan AI</h3><ul><li v-for="r in detail.ai.reasons" :key="r">{{r}}</li></ul><h3>Risiko & inspeksi</h3><ul><li v-for="r in detail.ai.risks" :key="r">{{r}}</li></ul><div class="info-note">Harga indikatif AI: {{idr(detail.ai.indicativeSellPrice)}} · Waktu jual indikatif: {{detail.ai.daysMin??'?'}}–{{detail.ai.daysMax??'?'}} hari. Keduanya belum terverifikasi.</div><button class="primary" @click="setWatch(detail)"><Bookmark :size="17"/>{{detail.watchlisted?'Hapus dari bid board':'Simpan ke bid board'}}</button></section></div>
 <div v-if="edit" class="modal-backdrop" @click.self="edit=null"><form class="modal wide" @submit.prevent="saveLot"><button type="button" class="modal-close icon-button" @click="edit=null"><X/></button><span class="eyebrow">VERIFY THE FACTS</span><h2>Periksa lot {{edit.lot_number}}</h2><div v-if="error" class="error">{{error}}</div><div class="source-quote">Halaman {{edit.data.sourcePage||'?'}} · {{edit.data.sourceQuote||'Kutipan sumber tidak tersedia'}}</div><div class="field-grid"><label>Nomor lot<input v-model="edit.data.lotNumber" required></label><label>Nama unit<input v-model="edit.data.vehicle" required></label><label>Tahun<input v-model.number="edit.data.year" type="number" min="1950" max="2100"></label><label>Transmisi<select v-model="edit.data.transmission"><option value="UNKNOWN">Belum diketahui</option><option value="MT">MT</option><option value="AT">AT / CVT</option></select></label><label>Kilometer<input v-model.number="edit.data.kilometer" type="number" min="0"></label><label>Harga dasar<input v-model.number="edit.data.basePrice" type="number" min="0"></label><label>STNK<select v-model="edit.data.stnk"><option value="UNKNOWN">Belum diketahui</option><option value="ADA">Ada</option><option value="TIDAK_ADA">Tidak ada</option></select></label><label>BPKB<select v-model="edit.data.bpkb"><option value="UNKNOWN">Belum diketahui</option><option value="ADA">Ada</option><option value="TIDAK_ADA">Tidak ada</option></select></label><label>Jatuh tempo pajak<input v-model="edit.data.taxExpiry" type="date"></label><label>Estimasi servis aktual<input v-model.number="edit.data.repairCost" type="number" min="0" placeholder="Kosong = buffer"></label><label>Pajak / balik nama aktual<input v-model.number="edit.data.taxCost" type="number" min="0" placeholder="Kosong = buffer"></label><label>Biaya tambahan unit<input v-model.number="edit.data.otherCost" type="number" min="0"></label></div><label>Catatan kondisi & dokumen<textarea v-model="edit.data.notes" rows="3"/></label><h3>Pembanding harga</h3><p class="muted">Gunakan unit dengan tipe, tahun, kondisi, dan lokasi yang sebanding. Harga listing adalah harga penawaran.</p><div v-for="(c,i) in edit.data.comparables" :key="i" class="comparable"><input v-model="c.url" type="url" placeholder="https://…" required><input v-model.number="c.price" type="number" min="1" placeholder="Harga IDR" required><input v-model="c.observedDate" type="date" required><button type="button" class="icon-button" @click="edit.data.comparables.splice(i,1)"><X :size="16"/></button></div><button type="button" class="secondary" @click="edit.data.comparables.push({url:'',price:null,observedDate:new Date().toLocaleDateString('en-CA'),notes:''})">+ Tambah pembanding</button><div class="checks"><label><input v-model="edit.verified" type="checkbox"> Saya sudah memeriksa data lot terhadap sumber.</label></div><div class="info-note">Perubahan ini berlaku pada analisis berikutnya. Jalankan analisis ulang untuk memperbarui ranking.</div><button class="primary" :disabled="busy">Simpan lot <Check :size="17"/></button></form></div>
 </div>
</template>
